(6099317, 898572, 15711, '<td valign="top">Uh oh, you are opening up a can of worms for the religious right with this one. LOL  Love the bokeh.</td>', 'Uh oh, you are opening up a can of worms for the religious right with this one. LOL  Love the bokeh.', '2010-07-21 08:52:58.000000', NULL, 1),
