INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6101047, 898111, 112218, '<td valign="top">Interesting editing.</td>', 'Interesting editing.', '2010-07-22 14:15:28.000000', NULL, 1),
(6101050, 898547, 112218, '<td valign="top">Horn seems rather asymmetrical - spoiling the image IMO.</td>', 'Horn seems rather asymmetrical - spoiling the image IMO.', '2010-07-22 14:16:16.000000', NULL, 1),
(6101051, 898051, 112218, '<td valign="top">Different idea!</td>', 'Different idea!', '2010-07-22 14:16:38.000000', NULL, 1),
(6101052, 897697, 112218, '<td valign="top">Ha ha!!!<br/>Alternative view.</td>', 'Ha ha!!!Alternative view.', '2010-07-22 14:17:28.000000', NULL, 1),
(6101054, 898539, 112218, '<td valign="top">And this was taken....?</td>', 'And this was taken....?', '2010-07-22 14:18:01.000000', NULL, 1),
(6101055, 898516, 114225, '<td valign="top">Brilliantly done! Love the mystery of looking through the trees, and the lighting you chose.</td>', 'Brilliantly done! Love the mystery of looking through the trees, and the lighting you chose.', '2010-07-22 14:18:23.000000', NULL, 1),
(6101056, 898701, 112218, '<td valign="top">Glad they''re not that big in real life!!!</td>', 'Glad they''re not that big in real life!!!', '2010-07-22 14:18:39.000000', NULL, 1),
(6101057, 898642, 112218, '<td valign="top">Weird.</td>', 'Weird.', '2010-07-22 14:19:01.000000', NULL, 1),
(6101058, 898581, 112218, '<td valign="top">Excellent!!!</td>', 'Excellent!!!', '2010-07-22 14:19:35.000000', NULL, 1),
(6101060, 898539, 114225, '<td valign="top">This is super cool. I like the B&amp;W you did, although I wonder what it would have been like with some color, to show off the sliminess of Alien.</td>', 'This is super cool. I like the B&W you did, although I wonder what it would have been like with some color, to show off the sliminess of Alien.', '2010-07-22 14:19:58.000000', NULL, 1),
(6101061, 898664, 112218, '<td valign="top">Image rather confused at a glance.</td>', 'Image rather confused at a glance.', '2010-07-22 14:20:10.000000', NULL, 1),
(6101062, 898701, 114225, '<td valign="top">The next sci-fi original movie will be calling you for their special effects :)<br/>Good choice of subdued colors.</td>', 'The next sci-fi original movie will be calling you for their special effects :)Good choice of subdued colors.', '2010-07-22 14:20:39.000000', NULL, 1),
(6101064, 898078, 112218, '<td valign="top">Something really mythical here!</td>', 'Something really mythical here!', '2010-07-22 14:20:51.000000', NULL, 1),
(6101065, 897941, 112218, '<td valign="top">Very good.</td>', 'Very good.', '2010-07-22 14:21:12.000000', NULL, 1),
(6101067, 898631, 114225, '<td valign="top">I like the idea a lot, and the balanced composition is well done. I think I would have liked the theme more overall if she were dressed up in a bit more fantasy garb.</td>', 'I like the idea a lot, and the balanced composition is well done. I think I would have liked the theme more overall if she were dressed up in a bit more fantasy garb.', '2010-07-22 14:21:34.000000', NULL, 1),
(6101068, 898626, 112218, '<td valign="top">Ingenious.</td>', 'Ingenious.', '2010-07-22 14:21:56.000000', NULL, 1),
(6101069, 898058, 114225, '<td valign="top">Some photos, the vintage feel really adds a lot to. For this one, I don''t think it does (sorry!).</td>', 'Some photos, the vintage feel really adds a lot to. For this one, I don''t think it does (sorry!).', '2010-07-22 14:22:07.000000', NULL, 1),
(6101070, 898253, 112218, '<td valign="top">Woody seems not to be grounded - gives the impression of floating.</td>', 'Woody seems not to be grounded - gives the impression of floating.', '2010-07-22 14:22:43.000000', NULL, 1),
(6101071, 898600, 114225, '<td valign="top">Great use of depth of field, nice colors, and nice details. It doesn''t seem very mythical to me, however.</td>', 'Great use of depth of field, nice colors, and nice details. It doesn''t seem very mythical to me, however.', '2010-07-22 14:22:52.000000', NULL, 1),
(6101072, 897722, 112218, '<td valign="top">?????????</td>', '?????????', '2010-07-22 14:23:13.000000', NULL, 1),
(6101074, 898564, 112218, '<td valign="top">Sorry but don''t "get" this....</td>', 'Sorry but don''t "get" this....', '2010-07-22 14:24:00.000000', NULL, 1),
(6101076, 898631, 112218, '<td valign="top">Where can I get some wings like this?</td>', 'Where can I get some wings like this?', '2010-07-22 14:24:38.000000', NULL, 1),
(6101077, 898267, 112218, '<td valign="top">Very weird</td>', 'Very weird', '2010-07-22 14:25:01.000000', NULL, 1),
(6101078, 898428, 114225, '<td valign="top">That''s creepy. I especially like the bright spots in the background. It makes it feel like even more is watching you than meets the eye (snicker).</td>', 'That''s creepy. I especially like the bright spots in the background. It makes it feel like even more is watching you than meets the eye (snicker).', '2010-07-22 14:25:44.000000', NULL, 1),
(6101079, 898553, 112218, '<td valign="top">I feel that the hair caught under her right arm should have been loose in the wind.<br/>Also, she appears uncomfortable - hunched.<br/>Good idea.</td>', 'I feel that the hair caught under her right arm should have been loose in the wind.Also, she appears uncomfortable - hunched.Good idea.', '2010-07-22 14:26:54.000000', NULL, 1),
(6101080, 898698, 114225, '<td valign="top">You might want to get that checked out... :)<br/>I like the blending you did between the horse/human parts. I would suggest that the lighting for the human be changed to match the lighting for the scene. It looks odd to have a right side light on the trees and a front/top light for the body.</td>', 'You might want to get that checked out... :)I like the blending you did between the horse/human parts. I would suggest that the lighting for the human be changed to match the lighting for the scene. It looks odd to have a right side light on the trees and a front/top light for the body.', '2010-07-22 14:28:21.000000', NULL, 1),
(6101081, 898188, 114225, '<td valign="top">The composition and colors of this photo are good (nice choice on background). However, the noise and reflections are taking away from it a bit. It would have been cool it you could have gotten the bubble in complete focus as well.</td>', 'The composition and colors of this photo are good (nice choice on background). However, the noise and reflections are taking away from it a bit. It would have been cool it you could have gotten the bubble in complete focus as well.', '2010-07-22 14:30:07.000000', NULL, 1),
(6101082, 898517, 114225, '<td valign="top">Love the idea behind this. It''s too bad you didn''t add a real mythical style to it, because it''s probably getting hammered by "shoehorn" or "dnmc" comments.</td>', 'Love the idea behind this. It''s too bad you didn''t add a real mythical style to it, because it''s probably getting hammered by "shoehorn" or "dnmc" comments.', '2010-07-22 14:30:54.000000', NULL, 1),
(6101083, 898588, 114225, '<td valign="top">Good subject for the challenge. Might I suggest trying out the advanced editing techniques to replace the background with something less distracting. Looks like you were near water, so maybe there was some sand you could have photographed and later combined.</td>', 'Good subject for the challenge. Might I suggest trying out the advanced editing techniques to replace the background with something less distracting. Looks like you were near water, so maybe there was some sand you could have photographed and later combined.', '2010-07-22 14:32:07.000000', NULL, 1),
(6101085, 898590, 114225, '<td valign="top">With a title for that, you must be going for as many DMNC votes as possible. :)</td>', 'With a title for that, you must be going for as many DMNC votes as possible. :)', '2010-07-22 14:32:45.000000', NULL, 1),
(6101086, 897952, 112218, '<td valign="top">Eeeewwww!!!!</td>', 'Eeeewwww!!!!', '2010-07-22 14:33:56.000000', NULL, 1),
(6101087, 898374, 114225, '<td valign="top">This is a nice idea for the challenge. While the composition is ok, I think this had a chance for even more pop. It might have been good to just get the head/shoulders (with wings of course) in a closeup view. Maybe even have her at the corner of the photo, just kind of peaking into the frame (PM me if this doesn''t make sense).</td>', 'This is a nice idea for the challenge. While the composition is ok, I think this had a chance for even more pop. It might have been good to just get the head/shoulders (with wings of course) in a closeup view. Maybe even have her at the corner of the photo, just kind of peaking into the frame (PM me if this doesn''t make sense).', '2010-07-22 14:34:22.000000', NULL, 1),
(6101090, 898471, 114225, '<td valign="top">Wonderful shot. Good vibrant colors (what I would expect in a land of fairies). Good costume, pose, and reflection.</td>', 'Wonderful shot. Good vibrant colors (what I would expect in a land of fairies). Good costume, pose, and reflection.', '2010-07-22 14:35:16.000000', NULL, 1),
(6101091, 897901, 112218, '<td valign="top">Pity the giant''s right elbow touches the structure but a good idea.</td>', 'Pity the giant''s right elbow touches the structure but a good idea.', '2010-07-22 14:35:20.000000', NULL, 1),
(6101092, 898586, 114225, '<td valign="top">Great idea for this challenge. I like how the pig is tilted a bit to give the viewer a sense of motion.</td>', 'Great idea for this challenge. I like how the pig is tilted a bit to give the viewer a sense of motion.', '2010-07-22 14:36:03.000000', NULL, 1),
(6101095, 898553, 114225, '<td valign="top">Great setup for this shot. You picked out a perfect costume, and the bow style is great. I''m torn on if I would have liked it more in portrait mode than landscape.</td>', 'Great setup for this shot. You picked out a perfect costume, and the bow style is great. I''m torn on if I would have liked it more in portrait mode than landscape.', '2010-07-22 14:37:19.000000', NULL, 1),
